public int search(int[] nums, int target) {
        int l = -1, r = nums.length;
        while (l + 1 < r) {
            int mid = l + (r - l) / 2;
            if (nums[mid] == target) {
                return mid;
            }
            if (nums[mid] >= nums[0]) {
                if (target >= nums[0] && target < nums[mid]) {
                    r = mid;
                } else {
                    l = mid;
                }
            } else {
                // target == nums[0] 属于左段（含下标 0），不能划进右段
                if (target < nums[0] && target >= nums[mid]) {
                    l = mid;
                } else {
                    r = mid;
                }
            }
        }
        return -1;
    }

